    RetainRule.add_member(:interval_unit, Smithy::Schema::Shapes::ShapeRef.new(shape: RetentionIntervalUnitValues, location_name: 'IntervalUnit', traits: {"smithy.api#documentation" => "<p>The unit of time for time-based retention. For example, to retain snapshots for 3 months, specify \n\t\t\t<code>Interval=3</code> and <code>IntervalUnit=MONTHS</code>. Once the snapshot has been retained for \n\t\t\t3 months, it is deleted, or it is moved to the archive tier if you have specified an \n\t\t\t<a href=\"https://docs.aws.amazon.com/dlm/latest/APIReference/API_ArchiveRule.html\">ArchiveRule</a>.</p>"}))
    RetainRule.type = Types::RetainRule
