    Schedule.add_member(:cross_region_copy_rules, Smithy::Schema::Shapes::ShapeRef.new(shape: CrossRegionCopyRules, location_name: 'CrossRegionCopyRules', traits: {"smithy.api#documentation" => "<p>Specifies a rule for copying snapshots or AMIs across Regions.</p>\n         <note>\n            <p>You can't specify cross-Region copy rules for policies that create snapshots on an \n\t\t\t\tOutpost or in a Local Zone. If the policy creates snapshots in a Region, then snapshots \n\t\t\t\tcan be copied to up to three Regions or Outposts.</p>\n         </note>"}))
